{
  "triples": [
    {
      "subject": "Neural Argument Generation",
      "predicate": "uses",
      "object": "sequence-to-sequence (seq2seq) framework",
      "object_type": "Method",
      "source_sentence": "our neural argument generation model adopts the popular encoder-decoder-based sequence-to-sequence (seq2seq) framework"
    },
    {
      "subject": "Automatic evaluation",
      "predicate": "uses",
      "object": "BLEU",
      "object_type": "Metric",
      "source_sentence": "Automatic evaluation based on BLEU shows that our framework generates better arguments than directly using retrieved sentences or popular seq2seq-based generation models that are also trained with retrieved evidence"
    }
  ]
}

{"triples": [
    {
      "subject": "Filtering",
      "predicate": "produces",
      "object": "dataset",
      "object_type": "Dataset",
      "source_sentence": "After filtering, the resultant dataset contains 26,525 OPs along with 305,475 relatively high quality root replies."
    }
  ]}

{
  "triples": [
    {
      "subject": "Attention Mechanism",
      "predicate": "designedFor",
      "object": "argument decoding",
      "object_type": "Task",
      "source_sentence": "attention mechanism is designed for argument decoding by attending both input and the previously generated keyphrases."
    },
    {
      "subject": "Beam Search",
      "predicate": "addresses",
      "object": "topic-relevant generations",
      "object_type": "Concept",
      "source_sentence": "Finally, a reranking-based beam search decoder is introduced to promote topic-relevant generations."
    },
    {
      "subject": "Words",
      "predicate": "uses",
      "object": "offensive words",
      "object_type": "Dataset",
      "source_sentence": "We use offensive words collected by Google's What Do You Love project."
    },
    {
      "subject": "Wikipedia",
      "predicate": "uses",
      "object": "English Wikipedia abstracts",
      "object_type": "Dataset",
      "source_sentence": "About 1.3 million English Wikipedia abstracts are down- loaded from http://dbpedia.org/page/."
    },
    {
      "subject": "Keywords",
      "predicate": "uses",
      "object": "sample keywords",
      "object_type": "Dataset",
      "source_sentence": "Sample keywords for politics: \"congress\", \"election\", \"constitution\"; for non-politics: \"art\", \"fashion\",\"music\"."
    }
  ]
}

{
  "triples": [
    {
      "subject": "evidence",
      "predicate": "uses",
      "object": "Wikipedia",
      "object_type": "Other",
      "source_sentence": "xE contains relevant evidence that is extracted from Wikipedia based on a separate retrieval module."
    },
    {
      "subject": "BiLSTM",
      "predicate": "uses",
      "object": "encoder hidden states",
      "object_type": "Other",
      "source_sentence": "A two-layer bidirectional LSTM (bi-LSTM) is used to obtain the encoder hidden states hi for each time step i."
    },
    {
      "subject": "GloVe",
      "predicate": "uses",
      "object": "word representations",
      "object_type": "Other",
      "source_sentence": "Word representations are initialized with 200-dimensional pre-trained GloVe embeddings, and updated during training."
    },
    {
      "subject": "Softmax",
      "predicate": "uses",
      "object": "non-linear transformation",
      "object_type": "Other",
      "source_sentence": "with each term estimated by a softmax function over a non-linear transformation of decoder hidden states sa t and sp t, for argument decoder and keyphrase decoder, respectively."
    }
  ]
}

{
  "triples": [
    {
      "subject": "Argument Generation",
      "predicate": "uses",
      "object": "<arg>",
      "object_type": "Other",
      "source_sentence": "A special token <arg> is inserted between the two sequences, indicating the start of argument generation."
    }
  ]
}

{
