}

{
  "triples": [
    {
      "subject": "Dropout",
      "predicate": "uses",
      "object": "RNN cells",
      "object_type": "Other",
      "source_sentence": "We apply dropout on RNN cells with a keep probability of 0.8."
    },
    {
      "subject": "ADAM",
      "predicate": "uses",
      "object": "initial learning rate",
      "object_type": "Other",
      "source_sentence": "We use Adam with an initial learning rate of 0.001 to optimize the cross-entropy loss."
    },
    {
      "subject": "Pre-training",
      "predicate": "uses",
      "object": "seq2seq model",
      "object_type": "Model",
      "source_sentence": "We pre-train a two-layer seq2seq model with OP as input and target argument as output from our training set."
    },
    {
      "subject": "training",
      "predicate": "uses",
      "object": "three stages",
      "object_type": "Other",
      "source_sentence": "We train the models in three stages where the truncated input and output lengths are gradually increased."
    }
  ]
}

{
  "triples": [
    {
      "subject": "retrieval",
      "predicate": "uses",
      "object": "evidence sentences",
      "object_type": "Other",
      "source_sentence": "We first consider a RETRIEVAL -based baseline, which concatenates retrieved evidence sentences to form the argument."
    },
    {
      "subject": "retrieval",
      "predicate": "uses",
      "object": "queries constructed from OP",
      "object_type": "Other",
      "source_sentence": "For test time, evidence sentences are retrieved with queries constructed from OP (System Retrieval )."
    },
    {
      "subject": "Seq2seq",
      "predicate": "uses",
      "object": "OP as input",
      "object_type": "Other",
      "source_sentence": "(1) SEQ2SEQ: training with OP as input and the argument as output;"
    },
    {
      "subject": "Seq2seq",
      "predicate": "uses",
      "object": "argument as output",
      "object_type": "Other",
      "source_sentence": "(1) SEQ2SEQ: training with OP as input and the argument as output;"
    },
    {
      "subject": "Seq2seq + encode evd",
      "predicate": "uses",
      "object": "evidence sentences",
      "object_type": "Other",
      "source_sentence": "(2) SEQ2SEQ + encode evd: augmenting input with evidence sentences as in our model;"
    },
    {
      "subject": "Seq2seq + encode KP",
      "predicate": "uses",
      "object": "gold-standard keyphrases",
      "object_type": "Other",
      "source_sentence": "(3) SEQ2SEQ + encode KP: augmenting input with gold-standard keyphrases, which assumes some of the talking points are known."
    },
    {
      "subject": "Seq2seq",
      "predicate": "uses",
      "object": "keyphrase attention",
      "object_type": "Other",
      "source_sentence": "For each, we further test whether adding keyphrase attention for argument decoding is helpful (+ attend KP)."
    },
    {
      "subject": "Seq2seq",
      "predicate": "uses",
      "object": "beam search decoder",
      "object_type": "Other",
      "source_sentence": "All seq2seq models use a regular beam search decoder with the same beam size as ours."
    }
  ]
}

